class DLMRefreshPolicy:
    """Stability-Aware Progressive Cache Relaxation (SAPCR).

    Novel contribution: Online prediction-stability tracking to adaptively
    gate cache refresh frequency during diffusion denoising.  Uses an EMA
    of token-level prediction agreement to progressively relax refresh
    intervals as predictions converge, and a volatility-weighted transfer
    ratio to focus scatter-refresh computation on uncertain tokens.

    Unlike dLLM-Cache (fixed intervals), d2Cache (active-query selection),
    or Elastic-Cache (tracked-window layer reset), SAPCR introduces a
    closed-loop feedback mechanism that adapts the cache policy to the
    denoising dynamics of each individual example and step.
    """

    policy_name = "sapcr"

    # Per-workload configuration tuned for quality gates first, then efficiency
    # gen_start: initial (conservative) gen refresh interval
    # gen_max: maximum interval when predictions are stable
    _CFG = {
    _CFG = {
        "math":      {"prompt_int": 50, "gen_start": 6,  "gen_max": 16, "base_transfer": 0.25},
        "humaneval": {"prompt_int": 50, "gen_start": 7,  "gen_max": 18, "base_transfer": 0.25},
        "lm_eval":   {"prompt_int": 50, "gen_start": 2,  "gen_max": 5,  "base_transfer": 0.25},
    }
    _STABILITY_THRESHOLD_TIGHTEN = 0.50 # EMA below this → tighten interval
    _EMA_ALPHA = 0.3                    # smoothing factor for stability EMA
    _MIN_TRANSFER = 0.15                # transfer ratio when stable
    _MAX_TRANSFER = 0.30                # transfer ratio when volatile
    _WARMUP_STEPS = 3                   # steps before adaptation kicks in

    def __init__(self):
        self._prev_preds = None
        self._stability_ema = 0.5       # start neutral
        self._current_gen_interval = None
        self._block_step_count = 0

    def _cfg(self, wl):
        return self._CFG.get(wl, self._CFG["math"])

    def block_schedule(self, request_meta):
        wl = WORKLOAD_CONFIGS[request_meta["workload"]]
        return {
            "gen_length": wl["gen_length"],
            "block_length": wl["block_length"],
            "num_steps": wl["num_steps"],
            "warmup_forward": False,
        }

    def query_plan(self, step_meta, mask_state, cache_state):
        return {
            "query_scope": "full_sequence",
            "query_positions": None,
            "track_positions": [],
            "masked_window": None,
        }

    def cache_refresh_plan(self, layer_meta, step_meta, token_stats, cache_state):
        wl = step_meta.get("workload", "math")
        cfg = self._cfg(wl)

        # Initialize on first call
        if self._current_gen_interval is None:
            self._current_gen_interval = cfg["gen_start"]

        # --- Core novelty: stability-gated interval adaptation ---
        # Only adapt after warmup to get a reliable stability estimate
        if self._block_step_count > self._WARMUP_STEPS:
            if self._stability_ema > self._STABILITY_THRESHOLD_RELAX:
                # Predictions are converging → safe to cache more aggressively
                self._current_gen_interval = min(
                    self._current_gen_interval + 1,
                    cfg["gen_max"],
                )
            elif self._stability_ema < self._STABILITY_THRESHOLD_TIGHTEN:
                # Predictions are volatile → tighten refresh to preserve quality
                self._current_gen_interval = max(
                    self._current_gen_interval - 1,
                    cfg["gen_start"],
                )

        # --- Volatility-weighted transfer ratio ---
        # Smoothly interpolate between min/max transfer based on stability
        if self._stability_ema > self._STABILITY_THRESHOLD_RELAX:
            transfer = self._MIN_TRANSFER
        elif self._stability_ema < self._STABILITY_THRESHOLD_TIGHTEN:
            transfer = self._MAX_TRANSFER
        else:
            t = (self._stability_ema - self._STABILITY_THRESHOLD_TIGHTEN) / max(
                self._STABILITY_THRESHOLD_RELAX - self._STABILITY_THRESHOLD_TIGHTEN, 1e-6
            )
            transfer = self._MAX_TRANSFER + t * (self._MIN_TRANSFER - self._MAX_TRANSFER)

        return {
            "use_feature_cache": True,
            "prompt_refresh_interval": cfg["prompt_int"],
            "gen_refresh_interval": self._current_gen_interval,
            "transfer_ratio": transfer,
            "row_selector": "lowest_value_feature_similarity",
            "kv_update": "scatter_refresh",
            "layer_reset": None,
        }

    def attention_probe_plan(self, layer_meta, step_meta):
        return {
            "need_attention_weights": False,
            "rollout_p": 0.0,
            "current_k": 0,
            "gamma": None,
            "track_num": 0,
        }

    def token_transfer_plan(self, logits, mask_state, step_meta):
        return {
            "mode": "low_confidence",
            "scope": "current_block",
            "num_transfer_tokens": step_meta["default_num_transfer_tokens"],
            "threshold": None,
            "force_one": True,
        }

    def after_step(self, step_meta, logits, attention_stats, transfer_state, cache_state):
        # --- Prediction stability tracking ---
        current_preds = logits.argmax(dim=-1) if hasattr(logits, 'argmax') else None

        if current_preds is not None and self._prev_preds is not None:
            if current_preds.shape == self._prev_preds.shape:
                agreement = (current_preds == self._prev_preds).float().mean().item()
                self._stability_ema = (
                    self._EMA_ALPHA * agreement
                    + (1.0 - self._EMA_ALPHA) * self._stability_ema
                )

        if current_preds is not None:
            self._prev_preds = current_preds.detach().clone()
        self._block_step_count += 1

        # Reset tracking state at block boundaries
        step_in_block = step_meta.get("step_in_block", 0)
        if step_in_block == 0 and step_meta.get("step", 0) > 0:
            # New block → reset adaptive state but keep stability memory
            cfg = self._cfg(step_meta.get("workload", "math"))
            self._current_gen_interval = cfg["gen_start"]
            # Carry over a damped stability signal across blocks
            self._stability_ema *= 0.5
            self._prev_preds = None
            self._block_step_count = 0

        return cache_state


