    step_meta = {
        "step": 0,
        "step_in_block": 0,
        "block": 0,
        "workload": workload_name,
        "regime": "final",
        "total_steps": _clamp_int(schedule.get("num_steps"), 1, WORKLOAD_CONFIGS[workload_name]["num_steps"]),
        "prompt_len": 0,
