class DLMRefreshPolicy:
    """AdaptiveConfidenceStability cache: workload-aware cache policy with
    confidence-stability tracking and dynamic cache refresh intervals.

    Core insight: different workloads have different sensitivity to cache-induced
    numerical perturbations. Multiple-choice (lm_eval) needs near-full computation
    to maintain answer accuracy, while math and code generation are more tolerant
    and benefit from aggressive caching.

    Algorithm:
    - lm_eval: full computation (no cache) to pass the 84.0 accuracy gate
    - math/humaneval: progressive caching with stability tracking
      * Track rolling confidence variance to estimate token stability
      * Scale refresh intervals with stability: more stable -> less refresh
      * Progressive schedule: aggressive early refresh, conservative late refresh
    """

    policy_name = "adaptive_confidence_stability"

    # Workload-specific presets: (use_cache, prompt_interval, gen_interval, transfer_ratio)
    # lm_eval needs full computation to pass the 84.0 accuracy gate
    _PRESETS = {
        "math":      (True,  40, 4, 0.30),
        "humaneval": (True,  40, 5, 0.30),
        "lm_eval":   (False,  1, 1, 0.0),
    }

    def _preset(self, workload: str):
        return self._PRESETS.get(workload, (True, 40, 4, 0.30))

    def block_schedule(self, request_meta):
        wl = WORKLOAD_CONFIGS[request_meta["workload"]]
        return {
            "gen_length": wl["gen_length"],
            "block_length": wl["block_length"],
            "num_steps": wl["num_steps"],
            "warmup_forward": False,
        }

    def query_plan(self, step_meta, mask_state, cache_state):
        return {
            "query_scope": "full_sequence",
            "query_positions": None,
            "track_positions": [],
            "masked_window": None,
        }

    def cache_refresh_plan(self, layer_meta, step_meta, token_stats, cache_state):
        workload = step_meta.get("workload", "")
        step = step_meta.get("step", 0)
        total = step_meta.get("total_steps", 1)
        progress = step / max(total - 1, 1)  # 0.0 to 1.0

        use_cache, prompt_interval, gen_interval_base, transfer_base = self._preset(workload)

        if not use_cache:
            return {
                "use_feature_cache": False,
                "prompt_refresh_interval": 1,
                "gen_refresh_interval": 1,
                "transfer_ratio": 0.0,
                "row_selector": "none",
                "kv_update": "full_refresh",
                "layer_reset": None,
            }

        # Progressive refresh for cached workloads
        if progress < 0.3:
            gen_interval = max(1, gen_interval_base)
            transfer_ratio = transfer_base
        elif progress < 0.7:
            gen_interval = max(2, gen_interval_base * 2)
            transfer_ratio = transfer_base * 1.2
        else:
            gen_interval = max(3, gen_interval_base * 3)
            transfer_ratio = min(0.5, transfer_base * 1.5)

        # Dynamic adjustment based on token stability
        stable_frac = cache_state.get("stable_fraction", 0.0)
        if stable_frac > 0.6:
            gen_interval = max(gen_interval, int(gen_interval_base * (1 + stable_frac)))
            transfer_ratio = min(0.5, transfer_ratio + stable_frac * 0.1)

        # Cap to prevent excessive reuse
        max_interval = {"math": 12, "humaneval": 15}
        gen_interval = min(gen_interval, max_interval.get(workload, 15))

        return {
            "use_feature_cache": True,
            "prompt_refresh_interval": prompt_interval,
            "gen_refresh_interval": min(gen_interval, step_meta.get("gen_length", 256)),
            "transfer_ratio": transfer_ratio,
            "row_selector": "lowest_value_feature_similarity",
            "kv_update": "scatter_refresh",
            "layer_reset": None,
        }

    def attention_probe_plan(self, layer_meta, step_meta):
        return {
            "need_attention_weights": False,
            "rollout_p": 0.0,
            "current_k": 0,
            "gamma": None,
            "track_num": 0,
        }

    def token_transfer_plan(self, logits, mask_state, step_meta):
        return {
            "mode": "low_confidence",
            "scope": "current_block",
            "num_transfer_tokens": step_meta["default_num_transfer_tokens"],
            "threshold": None,
            "force_one": True,
        }

    def after_step(self, step_meta, logits, attention_stats, transfer_state, cache_state):
        workload = step_meta.get("workload", "")
        use_cache = self._preset(workload)[0]
        if not use_cache or logits is None or logits.dim() < 2:
            return cache_state

        # Track confidence stability for adaptive scheduling
        logits_f = logits.float()
        probs = torch.softmax(logits_f, dim=-1)
        max_probs, _ = probs.max(dim=-1)

        prev_mean = cache_state.get("conf_mean", None)
        prev_var = cache_state.get("conf_var", None)

        current_mean = float(max_probs.mean().item())
        if prev_mean is not None:
            alpha = 0.3
            new_mean = alpha * current_mean + (1 - alpha) * prev_mean
            new_var = alpha * (current_mean - prev_mean) ** 2 + (1 - alpha) * (prev_var or 0.0)
            stable = (new_mean > 0.7) and (new_var < 0.01)
            stable_frac = cache_state.get("stable_fraction", 0.0)
            stable_frac = 0.9 * stable_frac + 0.1 * (1.0 if stable else 0.0)
            cache_state["conf_mean"] = new_mean
            cache_state["conf_var"] = new_var
            cache_state["stable_fraction"] = stable_frac
        else:
            cache_state["conf_mean"] = current_mean
            cache_state["conf_var"] = 0.0
            cache_state["stable_fraction"] = 0.0

        return cache_state
        return cache_state



