class _D2ContextManager:
    def __init__(self, context, after=None):
        self.context = context
        self.after = after

    def __enter__(self):
        return self.context

    def __exit__(self, exc_type, exc, tb):
        if exc_type is None and self.after is not None:
            self.after(self.context)
