class DLMRefreshPolicy:
    """Adaptive PID-controlled feature cache with running statistics."""

    policy_name = "adaptive_pid"

    # Per-workload base intervals (prompt_interval, gen_interval, transfer_ratio)
    _BASE_PRESETS = {
        "math": (7, 50, 0.25),
        "humaneval": (8, 50, 0.25),
        "lm_eval": (3, 50, 0.25),
    }

    def block_schedule(self, request_meta):
        wl = WORKLOAD_CONFIGS[request_meta["workload"]]
        return {
            "gen_length": wl["gen_length"],
            "block_length": wl["block_length"],
            "num_steps": wl["num_steps"],
            "warmup_forward": False,
        }

    def query_plan(self, step_meta, mask_state, cache_state):
        return {
            "query_scope": "full_sequence",
            "query_positions": None,
            "track_positions": [],
            "masked_window": None,
        }

    def cache_refresh_plan(self, layer_meta, step_meta, token_stats, cache_state):
        workload = step_meta["workload"]
        base_prompt, base_gen, base_transfer = self._BASE_PRESETS.get(
            workload, (4, 50, 0.25)
        )

        # Initialize running averages if not present
        if "running_difficulty" not in cache_state:
            cache_state["running_difficulty"] = 0.5
            cache_state["running_similarity"] = 1.0
            cache_state["running_importance"] = 0.5

        # Compute current averages
        if token_stats:
            cur_difficulty = sum(t["difficulty"] for t in token_stats) / len(token_stats)
            cur_similarity = sum(t["similarity"] for t in token_stats) / len(token_stats)
            cur_importance = sum(t["importance"] for t in token_stats) / len(token_stats)
            # Update running averages with exponential smoothing (alpha = 0.3)
            alpha = 0.3
            cache_state["running_difficulty"] = alpha * cur_difficulty + (1 - alpha) * cache_state["running_difficulty"]
            cache_state["running_similarity"] = alpha * cur_similarity + (1 - alpha) * cache_state["running_similarity"]
            cache_state["running_importance"] = alpha * cur_importance + (1 - alpha) * cache_state["running_importance"]
        else:
            cur_difficulty = cache_state["running_difficulty"]
            cur_similarity = cache_state["running_similarity"]
            cur_importance = cache_state["running_importance"]

        # Adjust intervals based on running difficulty (PID-like)
        # Target difficulty = 0.5, adjust gen_interval to bring difficulty towards target
        target = 0.5
        diff_error = cur_difficulty - target
        # Proportional control: adjust gen_interval inversely proportional to error
        # If difficulty higher than target, reduce interval (refresh more)
        p_gain = 0.5  # scaling factor
        gen_adjust = 1.0 + p_gain * diff_error  # >1 if diff_error positive? Actually if diff_error positive (difficulty high), we want smaller interval, so gen_adjust <1.
        # Let's compute factor = 1 / (1 + p_gain * diff_error) to decrease interval when diff positive.
        factor = 1.0 / (1.0 + p_gain * diff_error) if diff_error > 0 else (1.0 + p_gain * abs(diff_error))
